$d="Z:\AAA-GitHub-Repositories\n5-study-app\images\kanji-animated"; $s="Z:\AAA-GitHub-Repositories\n5-study-app\images\svgsJa"; New-Item -ItemType Directory -Force -Path $d | Out-Null; $c=Get-Content "Z:\AAA-GitHub-Repositories\n5-study-app\js\data\kanjiData.js" -Raw; $m=[regex]::Matches($c, "[\u4e00-\u9faf]"); $l=@(); foreach($x in $m){$l+=$x.Value}; $l=$l|Select-Object -Unique; Write-Host "Found $($l.Count) kanji" -ForegroundColor Cyan; $copied=0;$missing=0; foreach($k in $l){$bytes=[System.Text.Encoding]::UTF32.GetBytes($k); $dec=[System.BitConverter]::ToUInt32($bytes,0); $src=Join-Path $s "$dec.svg"; $tgt=Join-Path $d "$dec.svg"; if(Test-Path $src){Copy-Item $src $tgt -Force; $copied++; Write-Host "✅ $k ($dec.svg)"}else{$missing++; Write-Host "❌ $k ($dec.svg)"}}; Write-Host "`n========================================"; Write-Host "Summary: ✅ Copied: $copied, ❌ Missing: $missing"; Write-Host "========================================"